import { CheckboxButton, CheckboxField, FieldError, Text } from "react-aria-components";
import type {
  CheckboxFieldProps as AriaCheckboxFieldProps,
  ValidationResult,
} from "react-aria-components";
import { createContext, useContext, type ReactNode, type Ref } from "react";
import "./Checkbox.css";

// Category A — borrows React Aria's CheckboxField (validation-capable) + CheckboxButton split
// (the deprecated single <Checkbox> is superseded). CheckboxField is the <div> wrapper that owns
// validation state + the description/error slots; CheckboxButton is the clickable <label> (box +
// label), and exposes isSelected/isIndeterminate for the glyph.

/* Check / indeterminate marks are the checkbox's OWN look (owned, not a
   general-purpose reicon icon): a 10×10 vector painted via currentColor so it
   inherits the box's selected foreground, sized by the check-size token. */
function CheckMark() {
  return (
    <svg
      className="sd-checkbox__icon"
      viewBox="0 0 10 10"
      fill="none"
      aria-hidden="true"
    >
      <path
        d="M8.37189 1.92596C8.60049 1.77516 8.89913 1.77518 9.12775 1.92596L9.23615 2.01385L9.32404 2.12225C9.50003 2.38908 9.47099 2.75166 9.23615 2.98651L4.23615 7.98651C3.96765 8.25482 3.53191 8.25493 3.26349 7.98651L0.763489 5.48651C0.49508 5.21808 0.495185 4.78235 0.763489 4.51385L0.871887 4.42596C1.10049 4.27517 1.39914 4.27519 1.62775 4.42596L1.73614 4.51385L3.74982 6.52752L8.26349 2.01385L8.37189 1.92596Z"
        fill="currentColor"
      />
    </svg>
  );
}

function IndeterminateMark() {
  return (
    <svg
      className="sd-checkbox__icon"
      viewBox="0 0 10 10"
      fill="none"
      aria-hidden="true"
    >
      <path
        d="M8.33398 4.3125C8.71338 4.31285 9.02148 4.62053 9.02148 5C9.02148 5.37947 8.71338 5.68715 8.33398 5.6875H1.66699C1.28729 5.6875 0.979492 5.37969 0.979492 5C0.979492 4.62031 1.28729 4.3125 1.66699 4.3125H8.33398Z"
        fill="currentColor"
      />
    </svg>
  );
}

export type CheckboxSize = "small" | "medium" | "large";

/** A CheckboxGroup's size, relayed to the checkboxes inside it (the SegmentedControl idiom). The
    group owns the size of its items, so inside one it wins over a checkbox's own `size`. */
export const CheckboxSizeContext = createContext<CheckboxSize | undefined>(undefined);

export type CheckboxGroupVariant = "standard" | "filled";
/** A CheckboxGroup's `variant`, relayed the same way, as RadioGroup relays its own. */
export const CheckboxVariantContext = createContext<CheckboxGroupVariant>("standard");

export type CheckboxGroupIndicator = "box" | "check";
/** A CheckboxGroup's `indicator`, relayed the same way. */
export const CheckboxIndicatorContext = createContext<CheckboxGroupIndicator>("box");

export interface CheckboxProps
  extends Omit<AriaCheckboxFieldProps, "className" | "children"> {
  /**
   * Size axis: the box, its hit area, the row and the label's type role together. Inside a
   * CheckboxGroup the group's `size` applies instead.
   *
   * @default "medium"
   */
  size?: CheckboxSize;
  /** Checkbox label content. */
  children?: ReactNode;
  /** Helper text below the checkbox. */
  description?: string;
  /** Message shown when validation fails. */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Additional class (optional). sd-checkbox is always preserved. */
  className?: string;
  /** Forwarded to the underlying wrapper <div> DOM node (the input uses inputRef). */
  ref?: Ref<HTMLDivElement>;
}

export function Checkbox({
  size: sizeProp = "medium",
  children,
  description,
  errorMessage,
  className,
  ...props
}: CheckboxProps) {
  // Bare mode: no label ⇒ a label-less selection affordance (list-row select, select-all
  // header, data-grid cell). The box stands alone, so the interaction region (hover/pressed
  // state-layer + focus ring) hugs it as a symmetric square instead of spanning a label —
  // driven by `data-bare` on the button (§6 same-element attribute; no combinator).
  const isBare = children == null;
  const size = useContext(CheckboxSizeContext) ?? sizeProp;
  const variant = useContext(CheckboxVariantContext);
  const indicator = useContext(CheckboxIndicatorContext);
  // The round check stands at the row's trailing edge, after its label; a bare box has no label to
  // trail, so it keeps the square.
  const isCheck = indicator === "check" && !isBare;
  return (
    <CheckboxField
      {...props}
      data-bare={isBare || undefined}
      data-size={size}
      data-variant={variant === "filled" ? variant : undefined}
      data-indicator={isCheck ? indicator : undefined}
      className={className ? `sd-checkbox ${className}` : "sd-checkbox"}
    >
      {/* The label's type role sits on the <label> itself, the text element, so the box beside the
          text reads the label's own line box (`1lh`) to centre on its first line. */}
      <CheckboxButton
        className={`sd-checkbox__button sd-type-body-${size}`}
        data-bare={isBare || undefined}
        data-variant={variant === "filled" ? variant : undefined}
        data-indicator={isCheck ? indicator : undefined}
      >
        {({ isSelected, isIndeterminate }) => (
          <>
            <span aria-hidden="true" className="sd-checkbox__box">
              {isIndeterminate ? (
                <IndeterminateMark />
              ) : isSelected ? (
                <CheckMark />
              ) : null}
            </span>
            {!isBare && (
              <span className="sd-checkbox__label">
                {children}
              </span>
            )}
          </>
        )}
      </CheckboxButton>
      {description && (
        <Text slot="description" className={`sd-checkbox__description sd-type-caption-${size}`}>
          {description}
        </Text>
      )}
      <FieldError className={`sd-checkbox__error sd-type-caption-${size}`}>{errorMessage}</FieldError>
    </CheckboxField>
  );
}

/* CheckboxField wrapper (<div>): the field column — the clickable button on top, then the
   optional description / error. Validation + disabled state live here (RAC emits them on the
   field div); interaction state lives on __button below. */
.sd-checkbox {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--sd-checkbox-field-gap);
}
/* size — every size-dependent value is relayed from here as a `-current` intermediate, which the
   button, box, ring and helper lines inherit (contract §6 rule 5). Medium is the old single set. */
.sd-checkbox {
  --sd-checkbox-padding-inline-current: var(--sd-checkbox-padding-inline);
  /* the box's corner curve, and its halo's: `round` under the check indicator, whose radius is full. */
  --sd-checkbox-box-corner-shape-current: superellipse(var(--sd-radius-curve));
}
.sd-checkbox[data-size="small"] {
  --sd-checkbox-box-size-current: var(--sd-checkbox-box-size-small);
  --sd-checkbox-box-radius-current: var(--sd-checkbox-box-radius-small);
  --sd-checkbox-check-size-current: var(--sd-checkbox-check-size-small);
  --sd-checkbox-gap-current: var(--sd-checkbox-gap-small);
  --sd-checkbox-padding-block-current: var(--sd-checkbox-padding-block-small);
  --sd-checkbox-bare-padding-current: var(--sd-checkbox-bare-padding-small);
  --sd-checkbox-state-layer-spread-current: var(--sd-checkbox-state-layer-spread-small);
  --sd-checkbox-state-layer-radius-current: var(--sd-checkbox-state-layer-radius-small);
  --sd-checkbox-field-inset-current: var(--sd-checkbox-field-inset-small);
}
.sd-checkbox[data-size="medium"] {
  --sd-checkbox-box-size-current: var(--sd-checkbox-box-size-medium);
  --sd-checkbox-box-radius-current: var(--sd-checkbox-box-radius-medium);
  --sd-checkbox-check-size-current: var(--sd-checkbox-check-size-medium);
  --sd-checkbox-gap-current: var(--sd-checkbox-gap-medium);
  --sd-checkbox-padding-block-current: var(--sd-checkbox-padding-block-medium);
  --sd-checkbox-bare-padding-current: var(--sd-checkbox-bare-padding-medium);
  --sd-checkbox-state-layer-spread-current: var(--sd-checkbox-state-layer-spread-medium);
  --sd-checkbox-state-layer-radius-current: var(--sd-checkbox-state-layer-radius-medium);
  --sd-checkbox-field-inset-current: var(--sd-checkbox-field-inset-medium);
}
.sd-checkbox[data-size="large"] {
  --sd-checkbox-box-size-current: var(--sd-checkbox-box-size-large);
  --sd-checkbox-box-radius-current: var(--sd-checkbox-box-radius-large);
  --sd-checkbox-check-size-current: var(--sd-checkbox-check-size-large);
  --sd-checkbox-gap-current: var(--sd-checkbox-gap-large);
  --sd-checkbox-padding-block-current: var(--sd-checkbox-padding-block-large);
  --sd-checkbox-bare-padding-current: var(--sd-checkbox-bare-padding-large);
  --sd-checkbox-state-layer-spread-current: var(--sd-checkbox-state-layer-spread-large);
  --sd-checkbox-state-layer-radius-current: var(--sd-checkbox-state-layer-radius-large);
  --sd-checkbox-field-inset-current: var(--sd-checkbox-field-inset-large);
}
.sd-checkbox[data-disabled] {
  /* dim the whole field once at the wrapper (button opacity would miss description/error). */
  opacity: var(--sd-state-disabled);
}

/* CheckboxButton (<label>): the clickable interactive region — box + label, with the padded,
   rounded hover/press area (NavItem-style ghost overlay, ADR-0009). Rest transparent. */
.sd-checkbox__button {
  --sd-checkbox-box-background-current: var(--sd-checkbox-box-background);
  --sd-checkbox-box-border-current: var(--sd-checkbox-box-border);
  --sd-checkbox-box-foreground-current: transparent;
  /* box vertical offset: centred on the label's first line by default; zeroed in bare mode. `1lh`
     is the label's own line box (the role class is on this <label>, which the box inherits), so it
     holds at every size, in every brand and usage context. It was `1.5rem`, which is the default
     brand's medium line box only: 27px in mango and 25.5px in aronia, so the box sat 1.5 and 0.75px
     high there. The padding pair comes from the size rules on the root; bare mode replaces it. */
  --sd-checkbox-box-margin-block-start-current: calc((1lh - var(--sd-checkbox-box-size-current)) / 2);
  /* the hover/pressed state-layer + focus ring hug the BOX (compact square), never the label.
     Set per state here on the button; read on the box's ::before below (§5, combinator-free). */
  --sd-checkbox-state-layer-current: transparent;
  --sd-checkbox-ring-current: 0 0 0 0 transparent;
  --sd-checkbox-ring-outline-current: none;

  display: inline-flex;
  /* top-align so the box tracks the FIRST line of a wrapping label (nudged to center on that
     first line via the box margin below). */
  align-items: flex-start;
  gap: var(--sd-checkbox-gap-current);
  padding-block: var(--sd-checkbox-padding-block-current);
  padding-inline: var(--sd-checkbox-padding-inline-current);
  border-radius: var(--sd-checkbox-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-checkbox-background);
  color: var(--sd-checkbox-label-foreground);
  cursor: pointer;
  user-select: none;
  position: relative;
  outline: none;
}

/* Bare (label-less) mode — uniform padding so the click target squares up on the box; the box's
   label-centering offset is removed (no label to align to). The visual state-layer (box::before)
   already hugs the box in every mode, so bare only affects padding + offset. */
.sd-checkbox__button[data-bare] {
  --sd-checkbox-box-margin-block-start-current: 0;
  --sd-checkbox-padding-block-current: var(--sd-checkbox-bare-padding-current);
  --sd-checkbox-padding-inline-current: var(--sd-checkbox-bare-padding-current);
}

/* filled (CheckboxGroup `variant="filled"`) — the whole row is a box on the neutral fill and spans
   its column, so every box in a set is one width. The border keeps its width at rest, transparent,
   so a checked box colours its edge without moving its content. */
.sd-checkbox[data-variant="filled"] {
  display: flex;
  align-items: stretch;
}
.sd-checkbox__button[data-variant="filled"] {
  display: flex;
  padding: var(--sd-checkbox-padding-filled);
  border: var(--sd-checkbox-border-width) solid var(--sd-checkbox-border-filled);
  border-radius: var(--sd-checkbox-radius-filled);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-checkbox-background-filled);
}
.sd-checkbox__button[data-variant="filled"][data-selected] {
  border-color: var(--sd-checkbox-border-filled-selected);
  background: var(--sd-checkbox-background-filled-selected);
}

/* check (CheckboxGroup `indicator="check"`) — the label first and a round check at the trailing
   edge: the row spans its column, and `row-reverse` with `space-between` sets the box at the end and
   the label at the start without touching either part (the DOM keeps the box first; it is
   aria-hidden). The halo turns round with the box, and the helper lines start where the label does. */
.sd-checkbox[data-indicator="check"] {
  display: flex;
  align-items: stretch;
  --sd-checkbox-box-radius-current: var(--sd-checkbox-box-radius-check);
  --sd-checkbox-state-layer-radius-current: var(--sd-checkbox-box-radius-check);
  --sd-checkbox-field-inset-current: var(--sd-checkbox-padding-inline-current);
  --sd-checkbox-box-corner-shape-current: round;
}
/* filled under check: the label leads on a painted surface, whose padding is now the line, so the
   label takes the one text inset the plain button's inline padding gives it everywhere else
   (component-contract.md §6 rule 8). The box stays on the line; under `box` the box leads and the
   label keeps the plain gap. */
.sd-checkbox {
  --sd-checkbox-label-padding-inline-start-current: 0;
}
.sd-checkbox[data-variant="filled"][data-indicator="check"] {
  --sd-checkbox-label-padding-inline-start-current: var(--sd-checkbox-text-padding-inline);
}
.sd-checkbox__button[data-indicator="check"] {
  display: flex;
  flex-direction: row-reverse;
  justify-content: space-between;
}

.sd-checkbox__button[data-hovered] {
  --sd-checkbox-box-border-current: var(--sd-checkbox-box-border-hover);
  --sd-checkbox-state-layer-current: var(--sd-state-hover);
}
.sd-checkbox__button[data-selected],
.sd-checkbox__button[data-indeterminate] {
  --sd-checkbox-box-background-current: var(--sd-checkbox-box-background-selected);
  --sd-checkbox-box-border-current: var(--sd-checkbox-box-border-selected);
  --sd-checkbox-box-foreground-current: var(--sd-checkbox-box-foreground-selected);
}
.sd-checkbox__button[data-pressed] {
  --sd-checkbox-state-layer-current: var(--sd-state-pressed);
}
.sd-checkbox__button[data-invalid] {
  --sd-checkbox-box-border-current: var(--sd-checkbox-box-border-invalid);
}
.sd-checkbox__button[data-disabled] {
  cursor: not-allowed;
}
.sd-checkbox__button[data-readonly] {
  /* read-only: still focusable/valid, just not editable — signal via cursor. */
  cursor: default;
}
.sd-checkbox__button[data-focus-visible] {
  --sd-checkbox-ring-current: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  --sd-checkbox-ring-outline-current: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-checkbox__box {
  position: relative;
  display: inline-flex;
  flex: 0 0 auto;
  /* centred on the label's first line through the `1lh` intermediate set on the button above,
     which bare mode (no label) zeroes, keeping this combinator-free (§5). */
  margin-block-start: var(--sd-checkbox-box-margin-block-start-current);
  width: var(--sd-checkbox-box-size-current);
  height: var(--sd-checkbox-box-size-current);
  align-items: center;
  justify-content: center;
  background: var(--sd-checkbox-box-background-current);
  border: var(--sd-checkbox-box-border-width) solid var(--sd-checkbox-box-border-current);
  border-radius: var(--sd-checkbox-box-radius-current);
  corner-shape: var(--sd-checkbox-box-corner-shape-current);
  color: var(--sd-checkbox-box-foreground-current);
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard),
    color var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* Interaction state-layer + focus ring as a compact square hugging the box (ADR-0009), extending
   `state-layer-spread` beyond the box on every side (box 16 + 8×2 = 32). It renders on top of the
   box fill (translucent hover/pressed tint reads as a halo around the box) but behind the check
   glyph (a real DOM child). The label is never covered — the interactive affordance is the control.
   At 32px this also satisfies the WCAG 2.5.8 (24px) target the old transparent hit-area provided. */
.sd-checkbox__box::before {
  content: "";
  position: absolute;
  inset: calc(-1 * var(--sd-checkbox-state-layer-spread-current));
  /* The ring is a square around the box, so it takes the box's cap. Uncapped, 24px on this 32px
     square (box 16 + 8×2) clamps to a full circle, and a focused Checkbox reads as a Radio: the state
     `checkbox/box/radius`'s description exists to prevent. The cap sits in the token rather than here
     for the box radius's reason: Figma binds one resolved number, so a `min()` in CSS would cost the
     master's state-overlay and state-ring their binding. */
  border-radius: var(--sd-checkbox-state-layer-radius-current);
  corner-shape: var(--sd-checkbox-box-corner-shape-current);
  background: var(--sd-checkbox-state-layer-current);
  box-shadow: var(--sd-checkbox-ring-current);
  outline: var(--sd-checkbox-ring-outline-current);
  pointer-events: none;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* Check / indeterminate marks are the checkbox's own inline-SVG glyphs, sized by
   the check-size token and painted via the box's current foreground (currentColor).
   display:block removes the inline-SVG baseline gap so the glyph centers cleanly. */
.sd-checkbox__icon {
  display: block;
  width: var(--sd-checkbox-check-size-current);
  height: var(--sd-checkbox-check-size-current);
}

.sd-checkbox__label {
  padding-inline-start: var(--sd-checkbox-label-padding-inline-start-current);
  color: var(--sd-checkbox-label-foreground);
}

/* The helper lines belong to the LABEL, not the box, so they start on the label's axis: the
   button's own inline padding, then the box, then the gap between box and label. Built from the
   same tokens the button spends, so the two cannot drift (naming-convention § Text colour roles
   row 4 and token-contract § By relationship attachment: a supporting line binds to what it names). */
/* (the labelled inset is set per size at the top of this file.) bare (label-less): there is no label
   axis to start on, so the helper lines stand under the box, which the bare button's own uniform
   padding sets in from the edge, one text inset in from the box's start because the box is rounded
   (component-contract.md §6 rule 8, a field's own text). After the size rules, which it overrides
   at equal specificity. */
.sd-checkbox[data-bare] {
  --sd-checkbox-field-inset-current: calc(var(--sd-checkbox-bare-padding-current) + var(--sd-checkbox-text-padding-inline));
}
.sd-checkbox__description,
.sd-checkbox__error {
  padding-inline-start: var(--sd-checkbox-field-inset-current);
}

.sd-checkbox__description {
  color: var(--sd-checkbox-description-foreground);
}

.sd-checkbox__error {
  color: var(--sd-checkbox-error-foreground);
}
